  "关于与条款": "關於與條款",
  "免责条款": "免責條款",
  "查看软件使用声明与风险告知": "檢視軟體使用聲明與風險告知",
  "在使用 DeepSeek Harness 移动端前，请您仔细阅读并充分理解以下免责条款（特别是涉及风险告知与责任限制的内容）。如您不同意，本应用将直接退出；同意后可随时在「设置 → 免责条款」中查看。": "在使用 DeepSeek Harness Android 版前，請仔細閱讀並充分瞭解以下免責條款（特別是涉及風險告知與責任限制之內容）。若您不同意，本應用程式將直接結束；同意後可隨時於「設定 → 免責條款」中查閱。",
  "以下为 DeepSeek Harness 移动端的免责条款与使用风险告知，您可随时在此回看。": "以下為 DeepSeek Harness Android 版之免責條款與使用風險告知，您可隨時在此查閱。",
  "开源免费与按现状提供：本应用是基于 MIT 许可证发布的开源免费客户端软件，按「现状」提供。在适用法律允许的最大范围内，开发者不就本应用的适用性、准确性、连续性、稳定性或不侵权作任何明示或默示担保。官方不会通过本应用收取激活费或代装费。": "開源免費與依現狀提供：本應用程式係依 MIT 授權條款釋出之開源免費軟體，依「現狀（AS IS）」提供。在適用法律允許之最大範圍內，開發者不就本應用程式之適用性、正確性、連續性、穩定性或不侵權作任何明示或默示擔保。官方不會透過本應用程式收取啟用費或代為安裝費。",
  "AI 输出与第三方模型服务：本应用仅为本地客户端工具，不直接提供 AI 模型服务。AI 自动生成的内容、代码与设备操作建议可能存在错误、幻觉或遗漏，不构成法律、医疗、金融等专业意见，请务必在使用或执行前自行核验。您自行配置的第三方模型服务、API 凭据、计费规则及数据处理，均由您与对应服务商依据其服务条款独立承担责任。": "AI 輸出與第三方模型服務：本應用程式僅為本機用戶端工具，並不直接提供 AI 模型服務。AI 自動生成之內容、程式碼與裝置操作建議可能存在錯誤、幻覺或遺漏，不構成法律、醫療、財務等專業意見，請務必於使用或執行前自行查核確認。您自行設定之第三方模型服務、API 金鑰、計費方式與資料處理，均由您與該服務供應商依其服務條款各自負責。",
  "本地运行环境与高权限风险：本应用在设备本地运行 Ubuntu/PRoot 环境，并按您主动开启的权限提供文件访问、Shizuku、无障碍自动化、副屏及 KernelSU Root 等可选能力。启用高权限功能或确认执行系统命令可能修改、删除本机数据或影响系统及应用稳定性。在适用法律允许的最大范围内（法律规定不可免除的责任，如因故意或重大过失造成的损害除外），因您自行授权、配置或执行操作导致的数据丢失、设备故障或衍生损失，由使用者自行承担。": "本機執行環境與高權限風險：本應用程式於裝置本機執行 Ubuntu/PRoot 環境，並依您主動啟用之權限提供檔案存取、Shizuku、無障礙自動化、副螢幕及 KernelSU Root 等可選功能。啟用高權限功能或確認執行系統指令可能修改、刪除本機資料或影響系統與應用程式穩定性。在適用法律允許之最大範圍內（不包括法律規定不得預先免除之故意或重大過失責任），因您自行授權、設定或執行操作所生之資料遺失、裝置異常或相關損失，由使用者自行承擔。",
  "合法合规使用：您应严格遵守所适用司法管辖区的法律法规（含网络安全、数据安全与知识产权相关规定）及目标应用的服务条款。严禁将本应用及自动化、设备控制功能用于未授权访问、绕过付费或安全验证、侵害他人合法权益或任何违法违规用途。": "合法合規使用：您應嚴格遵守所適用司法管轄區之法律法規（包含資通安全、個人資料保護與智慧財產權相關規定）及目標應用程式之服務條款。嚴禁將本應用程式及自動化、裝置控制功能用於未授權存取、繞過付費或安全驗證、侵害他人合法權益或任何違法違規用途。",
  "本地数据与隐私边界：本应用的配置、运行日志与会话记录默认保存在您的设备本地，开发者不设立云端服务器收集上述用户内容。当您主动将文本、文件、媒体或屏幕内容交由 AI 处理时，相关数据将直接发送至您所选的第三方模型供应商并受其隐私政策与跨境传输规则约束；请勿在未获合法授权或充分评估的情况下传输敏感个人信息或机密资料，并请定期自行备份重要数据。": "本機資料與隱私界線：本應用程式之設定、執行紀錄與對話資料預設儲存於您的裝置本機，開發者不架設雲端伺服器收集前述使用者內容。當您主動將文字、檔案、媒體或螢幕畫面交由 AI 處理時，相關資料將直接傳送至您所選之第三方模型供應商，並適用其隱私權政策及跨境傳輸規範；請勿於未具合法依據或未妥善評估下傳送個人資料、敏感資訊或機密文件，並請自行定期備份重要資料。",
  "条款修改与版本更新：开发者有权根据适用法律法规变化、功能演进或安全需要修订本免责条款。如条款发生实质变更，本应用将通过应用内提示或版本更新予以公示，并在递增条款版本后重新征询您的同意；若您不同意修订内容，可随时停止使用并退出本应用。": "條款修訂與版本更新：開發者得因應適用法令變更、功能調整或資安需求修訂本免責條款。如條款發生實質變更，本應用程式將透過應用程式內提示或版本更新予以公告，並於提升條款版本後重新徵詢您的同意；若您不同意修訂內容，得隨時停止使用並結束本應用程式。",
  "权利保留条款：开发者未行使或延迟行使本条款项下的任何权利，不构成对该等权利的放弃；本条款及 MIT 许可证未明确授予的一切权利（包括但不限于项目名称、标识等相关权益）均依法予以保留。同时，本条款不影响您依据所在法域强制性法律享有的法定权利。": "權利保留條款：開發者未行使或延遲行使本條款項下之任何權利，均不構成對該等權利之拋棄；本條款及 MIT 授權條款未明示授與之一切權利（包含但不限於專案名稱、識別標誌等相關權益）均依法保留。同時，本條款不影響您依適用強制性法律所享有之法定權利。",
  "条款解释与效力：勾选同意并继续使用即表示您已充分阅读、理解并接受本免责条款。各小节标题仅为便于阅读，不影响条款实质含义；对本条款的说明与解释遵循诚实信用原则与通常理解，且不排除强制性法律规定的格式条款解释规则。若某一条款在特定司法管辖区被认定无效，不影响其余条款的效力。多语言版本仅供阅读参考；在不违反您所在法域强制性法律的前提下，不同语言版本存在理解差异时以中文简体文本为基准参考（适用法律要求以当地语言文本为准的，从其规定）。": "條款解釋與效力：勾選同意並繼續使用即表示您已充分閱讀、瞭解並接受本免責條款。各節標題僅為便於閱讀，不影響條款之實質意義；本條款之說明與解釋依誠實信用原則及通常理解為之，且不排除強制性法律關於定型化契約解釋之規定。若部分內容於特定法域被認定無效，不影響其餘條款之效力。多國語言版本僅供參考；在不牴觸您所在法域強制性法律之前提下，不同語言版本如有歧異，以簡體中文版本為基準參考（適用法律規定應以當地語言版本為準者，從其規定）。",
