  "请先了解每项权限的用途和风险。你可以取消勾选，也可以在系统提示中拒绝；未授权的功能会受限，其他功能仍可使用。": "請先了解每項權限的用途和風險。你可以取消勾選，也可以在系統提示中拒絕；未授權的功能會受限，其他功能仍可使用。",
  "确认后会依次弹出授权提示。悬浮窗、所有文件访问、无障碍和安装权限需要你在系统设置中手动选择，返回后继续下一项。": "確認後會依次彈出授權提示。懸浮窗、所有檔案存取、無障礙和安裝權限需要你在系統設定中手動選擇，返回後繼續下一項。",
  "联网用于模型请求、下载与更新；查询应用用于选择目标应用；前台服务、唤醒锁和开机恢复用于保持或恢复你已开启的服务。这些基础权限由系统自动管理，通常不会单独弹窗。联网可能消耗流量，后台运行可能增加耗电。": "聯網用於模型請求、下載與更新；查詢應用用於選擇目標應用；前臺服務、喚醒鎖和開機恢復用於保持或恢復你已開啟的服務。這些基礎權限由系統自動管理，通常不會單獨彈窗。聯網可能消耗流量，後臺執行可能增加耗電。",
  "Root 和屏幕捕获只在你主动使用相关功能时另行说明并确认，本次不会申请。授权不会自动开启悬浮球、自动化或设备命令功能；所有权限都可在系统设置中撤销。": "Root 和螢幕捕獲只在你主動使用相關功能時另行說明並確認，本次不會申請。授權不會自動開啟懸浮球、自動化或裝置命令功能；所有權限都可在系統設定中撤銷。",
  "正在处理：{0}": "正在處理：{0}",
  "请在系统设置中授权或返回。若系统页面未打开，或返回后没有继续，可点「继续下一项」重新检查结果。": "請在系統設定中授權或返回。若系統頁面未開啟，或返回後沒有繼續，可點「繼續下一項」重新檢查結果。",
  "继续下一项": "繼續下一項",
  "权限检查已完成。未授权的项目可在使用对应功能时重新申请。": "權限檢查已完成。未授權的專案可在使用對應功能時重新申請。",
