  "更新会替换 Ubuntu 运行时的系统目录。你的整个用户空间 /root（会话、模型密钥、Harness 设置、附件、技能、插件、工作区文件，以及你自己在 /root 下建的目录）都会保留；旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "更新會替換 Ubuntu 執行環境的系統目錄。你的整個使用者空間 /root（會話、模型金鑰、Harness 設定、附件、技能、外掛、工作區檔案，以及你自己在 /root 下建的目錄）都會保留；舊令牌與舊指令碼不會搬回，撞名沒搬回的項會留在「資料保留」裡可取回。",
  "更新会替换 Ubuntu 运行时的系统目录。你的整个用户空间 /root（会话、模型密钥、Harness 设置、附件、技能、插件、工作区文件，以及你自己在 /root 下建的目录）都会保留；终端里用 dsh plugin add 装的插件同样在插件目录里，不需要重装。旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "更新會替換 Ubuntu 執行環境的系統目錄。你的整個使用者空間 /root（會話、模型金鑰、Harness 設定、附件、技能、外掛、工作區檔案，以及你自己在 /root 下建的目錄）都會保留；終端裡用 dsh plugin add 裝的外掛同樣在外掛目錄裡，不需要重灌。舊令牌與舊指令碼不會搬回，撞名沒搬回的項會留在「資料保留」裡可取回。",
