  "通过系统前台服务提高运行时进程的存活优先级": "通過系統前臺服務提高執行環境程序的存活優先順序",
  "开启后需要常驻通知；锁屏、返回桌面或划掉最近任务后仍可能继续运行": "開啟後需要常駐通知；鎖屏、返回桌面或劃掉最近任務後仍可能繼續執行",
  "打开应用时预启动服务": "開啟應用時預啟動服務",
  "提前启动本机服务，点「打开对话」几乎立即进入；不会自动进入对话页": "提前啟動本機服務，點「開啟對話」幾乎立即進入；不會自動進入對話頁",
  "悬浮球": "懸浮球",
  "在其他应用上层显示悬浮球，点按展开快捷操作，长按打开 AI 对话小窗": "在其他應用上層顯示懸浮球，點按展開快捷操作，長按開啟 AI 對話小窗",
