  "申请通知权限": "申請通知權限",
  "开启实时动态": "開啟即時動態",
  "系统尚未允许本应用展示实况动态通知（如状态栏胶囊或兼容的超级岛）。部分机型对手动安装包会先收紧该开关：如有需要，请先在应用信息右上角「允许受限设置」，再到系统通知设置里开启「实时更新」或相关展示权限；是否展示仍由系统与厂商策略决定。": "系統尚未允許本應用顯示即時動態通知（如狀態列膠囊或相容的超級島）。部分機型對手動安裝包會預設收緊此開關：如有需要，請先在應用資訊右上角點選「允許受限設定」，再到系統通知設定中開啟「即時更新」或相關顯示權限；實際是否顯示仍由系統與廠商策略決定。",
  "需要重新连接": "需要重新連線",
  "应用进程已被系统结束，当前连接已失效。请重新连接以启动 Harness。": "應用程序已被系統結束，當前連線已失效。請重新連線以啟動 Harness。",
  "后台保持可以降低应用被系统结束的概率，但无法阻止所有电池优化或内存清理。进程停止后，需要重新连接 Harness。": "後臺保持可以降低應用被系統結束的機率，但無法阻止所有電池最佳化或記憶體清理。程序停止後，需要重新連線 Harness。",
  "Shizuku 只用于设备 Shell 的授权与连接状态检测、连接恢复辅助和健康检查；它不是 root，也不提供永久保活能力。未安装、未授权或断开时，设备 Shell 功能自动降级，不影响 Ubuntu 终端与 Harness。": "Shizuku 只用於裝置 Shell 的授權與連線狀態檢測、連線恢復輔助和健康檢查；它不是 root，也不提供永久保活能力。未安裝、未授權或斷開時，裝置 Shell 功能自動降級，不影響 Ubuntu 終端與 Harness。",
  "未获得通知权限：Android 13 及以上，前台服务的常驻通知需要通知权限；缺少它时服务仍可启动，只是看不到这条通知。请在系统设置中为本应用开启通知权限后重试。": "未獲得通知權限：Android 13 及以上，前臺服務的常駐通知需要通知權限；缺少它時服務仍可啟動，只是看不到這條通知。請在系統設定中為本應用開啟通知權限後重試。",
  "设置已保存，但后台保持未生效：前台服务未运行。这通常是系统后台限制（自启动 / 后台运行 / 省电策略）造成的；通知权限只决定常驻通知是否可见，不是服务启动的前提。": "設定已儲存，但後臺保持未生效：前臺服務未執行。這通常是系統後臺限制（自啟動 / 後臺執行 / 省電策略）造成的；通知權限只決定常駐通知是否可見，不是服務啟動的前提。",
  "设置已保存，但悬浮球未生效：前台服务未运行。系统可能拒绝了前台服务启动，或权限不足；请在系统设置中检查「显示在其他应用上层」与通知权限后重试。": "設定已儲存，但懸浮球未生效：前臺服務未執行。系統可能拒絕了前臺服務啟動，或權限不足；請在系統設定中檢查「顯示在其他應用上層」與通知權限後重試。",
