  "存储权限：媒体读取（T1）{0} · 所有文件访问（T2）{1}。外部工作区需要 T2。": "儲存權限：媒體讀取（T1）{0} · 所有檔案存取（T2）{1}。外部工作區需要 T2。",
  "inbox / outbox 不是工作区：dsh 的 write 工具写 /mnt/inbox、/mnt/outbox 会失败（实测 EACCES），这是预期行为；搬运只能走这里的按钮。": "inbox / outbox 不是工作區：dsh 的 write 工具寫 /mnt/inbox、/mnt/outbox 會失敗（實測 EACCES），這是預期行為；搬運只能走這裡的按鈕。",
