  "尚未授予「所有文件访问」。请到系统设置里为 DSH 手动开启；开启后回到本页会重新检查。没有该权限时只能用终端或控制台上传文件。": "尚未授予「所有檔案存取」。請到系統設定裡為 DSH 手動開啟；開啟後回到本頁會重新檢查。沒有該權限時只能用終端或主控台上傳檔案。",
  "当前系统不存在「所有文件访问」这一档，投递区无法启用；请改用终端或控制台上传文件。Harness 本身不受影响。": "當前系統不存在「所有檔案存取」這一檔，投遞區無法啟用；請改用終端或主控台上傳檔案。Harness 本身不受影響。",
  "已授予「所有文件访问」，但投递区目录仍不可读写；可能是系统限制或目录被占用。工作区与 Harness 不受影响。": "已授予「所有檔案存取」，但投遞區目錄仍不可讀寫；可能是系統限制或目錄被佔用。工作區與 Harness 不受影響。",
