  "选择要浏览的目录": "選擇要瀏覽的目錄",
  "这里的目录都是访客能看到的「外部工作区」：手机上的文件夹挂进访客的 /mnt/user/<序号>，可以直接读写；inbox / outbox 是批量搬运通道，只能靠按钮搬运。": "這裡的目錄都是訪客能看到的「外部工作區」：手機上的資料夾掛進訪客的 /mnt/user/<序號>，可以直接讀寫；inbox / outbox 是批次搬運通道，只能靠按鈕搬運。",
  "选一个目录浏览它的子目录；导入到工作区与导出工作区只对 inbox / outbox 有效。": "選一個目錄瀏覽它的子目錄；匯入到工作區與匯出工作區只對 inbox / outbox 有效。",
  "还没有挂进来的目录：在下面「目录」里添加一个手机上的目录，它会出现在这里。": "還沒有掛進來的目錄：在下面「目錄」裡新增一個手機上的目錄，它會出現在這裡。",
