  "已安装的 Ubuntu 运行环境会被清除，其中的用户数据（会话、密钥、插件等）一并删除，终端与 Harness 会话将立即结束。": "已安裝的 Ubuntu 執行環境會被清除，其中的使用者資料（會話、金鑰、外掛等）一併刪除，終端與 Harness 會話將立即結束。",
