  "更新 Ubuntu 运行环境": "更新 Ubuntu 執行環境",
  "当前 APK 内置了新版运行环境。继续后会替换 Ubuntu 运行时的系统目录；你的整个用户空间 /root（会话、模型密钥、Harness 设置、附件、技能、插件、工作区文件，以及你自己在 /root 下建的目录）都会保留，应用设置也不受影响；旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "當前 APK 內建了新版執行環境。繼續後會替換 Ubuntu 執行環境的系統目錄；你的整個使用者空間 /root（會話、模型金鑰、Harness 設定、附件、技能、外掛、工作區檔案，以及你自己在 /root 下建的目錄）都會保留，應用設定也不受影響；舊令牌與舊指令碼不會搬回，撞名沒搬回的項會留在「資料保留」裡可取回。",
  "当前 APK 内置了新版运行环境。继续后会替换 Ubuntu 运行时的系统目录；你的整个用户空间 /root 会保留（包括终端里用 dsh plugin add 装的插件），应用设置也不受影响，不需要重装任何东西；旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "當前 APK 內建了新版執行環境。繼續後會替換 Ubuntu 執行環境的系統目錄；你的整個使用者空間 /root 會保留（包括終端裡用 dsh plugin add 裝的外掛），應用設定也不受影響，不需要重灌任何東西；舊令牌與舊指令碼不會搬回，撞名沒搬回的項會留在「資料保留」裡可取回。",
