  "已内置 Node.js、Python 3 与常用工具（busybox、jq、unzip）；gcc 等编译工具不在包内；": "已內建 Node.js、Python 3 與常用工具（busybox、jq、unzip）；gcc 等編譯工具不在包內；",
  "如需访问手机文件或系统操作，请配合 Shizuku 设备 Shell。": "如需存取手機檔案或系統操作，請配合 Shizuku 裝置 Shell。",
  "首次使用需要安装 Ubuntu 运行环境（数百 MB）。应用内置的安装包可离线安装；使用在线来源时，建议通过 Wi-Fi 下载。": "首次使用需要安裝 Ubuntu 執行環境（數百 MB）。應用內建的安裝包可離線安裝；使用線上來源時，建議通過 Wi-Fi 下載。",
  "运行时下载地址不完整：请在「设置 → 后台」同时填写清单地址与 SHA-256（两者必须成对）。": "執行環境下載地址不完整：請在「設定 → 後臺」同時填寫清單地址與 SHA-256（兩者必須成對）。",
  "这个安装包没带运行时下载地址：安装会先解压 APK 内置的镜像；内置镜像缺失时需要先到「设置 → 后台」填写清单地址与 SHA-256（两者必须成对）。": "這個安裝包沒帶執行環境下載地址：安裝會先解壓 APK 內建的映象；內建映象缺失時需要先到「設定 → 後臺」填寫清單地址與 SHA-256（兩者必須成對）。",
