  "选择模型供应商并保存 API Key。密钥在本机加密保存，保存后不再显示。": "選擇模型供應商並儲存 API Key。金鑰在本機加密儲存，儲存後不再顯示。",
  "可登录 DeepSeek 账号，或选择模型供应商并保存 API Key。密钥在本机加密保存，保存后不再显示。": "可登入 DeepSeek 賬號，或選擇模型供應商並儲存 API Key。金鑰在本機加密儲存，儲存後不再顯示。",
  "打开 Harness 后，在侧栏「更多」菜单选择登录；登录完成后返回此页可刷新账号状态。": "開啟 Harness 後，在側欄「更多」選單選擇登入；登入完成後返回此頁可重新整理賬號狀態。",
  "开始对话前需登录 DeepSeek 账号、保存一份 API Key，或在下方「自定义供应商」里填好第三方接口。若状态尚未同步，或凭据来自 Harness 的其他来源，可以直接打开。": "開始對話前需登入 DeepSeek 賬號、儲存一份 API Key，或在下方「自定義供應商」裡填好第三方介面。若狀態尚未同步，或憑證來自 Harness 的其他來源，可以直接開啟。",
  "用第三方接口？这步可以跳过，装好环境后在「设置 → 模型供应商 → 自定义供应商」里填 Base URL 与密钥。": "用第三方介面？這步可以跳過，裝好環境後在「設定 → 模型供應商 → 自定義供應商」裡填 Base URL 與金鑰。",
  "开始对话前需登录 DeepSeek 账号或保存一份模型 API Key。": "開始對話前需登入 DeepSeek 賬號或儲存一份模型 API Key。",
