  "Shizuku 提供设备命令和文件操作能力，权限取决于其启动模式。未安装、未授权或断开时，设备工具不可用，不影响 Ubuntu 终端与 Harness。": "Shizuku 提供裝置命令和檔案操作能力，權限取決於其啟動模式。未安裝、未授權或斷開時，裝置工具不可用，不影響 Ubuntu 終端與 Harness。",
