  "当前生效：{0} · 默认动作上限 {1} · 默认冷却时间 {2} 毫秒 · 默认匹配延迟 {3} 毫秒": "當前生效：{0} · 預設動作上限 {1} · 預設冷卻時間 {2} 毫秒 · 預設匹配延遲 {3} 毫秒",
