  "暂停这个应用的自动化": "暫停這個應用的自動化",
  "只挡规则自动求值：设备桥的单次动作（AI 明确要求的那一下）照旧走白名单与敏感窗口判定；暂停期间被丢掉的事件会计入运行记录里的「拦截原因」。": "只擋規則自動求值：裝置橋的單次動作（AI 明確要求的那一下）照舊走白名單與敏感視窗判定；暫停期間被丟掉的事件會計入執行記錄裡的「攔截原因」。",
