  "请先安装并启动 Shizuku，再为本应用授权；": "請先安裝並啟動 Shizuku，再為本應用授權；",
  "授权可随时在「设置」页撤销；": "授權可隨時在「設定」頁撤銷；",
  "获得授权后才能使用设备 Shell。": "獲得授權後才能使用裝置 Shell。",
  "安装 / 打开 Shizuku": "安裝 / 開啟 Shizuku",
  "授权设备 Shell": "授權裝置 Shell",
  "Harness 对话界面基于官方前端，已适配手机屏幕和触控操作。模型、推理强度等选项仍在 Harness 中设置。": "Harness 對話介面基於官方前端，已適配手機螢幕和觸控操作。模型、推理強度等選項仍在 Harness 中設定。",
  "插件统一在设置页的「插件管理」中管理，应用不会静默关闭任何插件；需要更多插件时，可在 Harness 内的市场页面按需安装。": "外掛統一在設定頁的「外掛管理」中管理，應用不會靜默關閉任何外掛；需要更多外掛時，可在 Harness 內的市場頁面按需安裝。",
  "已检测到模型配置。Harness 启动后即可开始对话，也可随时返回这里管理运行环境和终端。": "已檢測到模型配置。Harness 啟動後即可開始對話，也可隨時返回這裡管理執行環境和終端。",
  "尚未检测到模型 API Key。请先配置密钥；如果已在 Harness 中配置，也可以直接打开。": "尚未檢測到模型 API Key。請先配置金鑰；如果已在 Harness 中配置，也可以直接開啟。",
  "尚未检测到模型凭据。可打开 Harness 登录 DeepSeek 账号，或先配置 API Key；如果已配置其他来源的凭据，也可以直接打开。": "尚未檢測到模型憑證。可開啟 Harness 登入 DeepSeek 賬號，或先配置 API Key；如果已配置其他來源的憑證，也可以直接開啟。",
  "应用只读取 Harness 中的凭据配置状态，无法确认凭据是否有效，也可能无法识别其他来源的凭据。": "應用只讀取 Harness 中的憑證配置狀態，無法確認憑證是否有效，也可能無法識別其他來源的憑證。",
  "去配置模型账号或 API Key": "去配置模型賬號或 API Key",
  "密钥在本机加密保存，保存后不再显示；": "金鑰在本機加密儲存，儲存後不再顯示；",
  "配置成功后本步骤会出现「打开 Harness」按钮；": "配置成功後本步驟會出現「開啟 Harness」按鈕；",
  "应用只读取 Harness 中的密钥配置状态，无法确认密钥是否有效，也可能无法识别其他来源的凭据。": "應用只讀取 Harness 中的金鑰配置狀態，無法確認金鑰是否有效，也可能無法識別其他來源的憑證。",
  "去配置 API Key": "去配置 API Key",
  "我已在 Harness 内配置过，仍要打开": "我已在 Harness 內配置過，仍要開啟",
  "还没有可用的模型凭据": "還沒有可用的模型憑證",
  "没有密钥时每一轮对话都会失败，因此应用不会打开 Harness；保存一次 API Key 即可。若状态尚未同步，或凭据来自 Harness 的其他来源，可以直接打开。": "沒有金鑰時每一輪對話都會失敗，因此應用不會開啟 Harness；儲存一次 API Key 即可。若狀態尚未同步，或憑證來自 Harness 的其他來源，可以直接開啟。",
  "上一步": "上一步",
