  "Harness 未提供有效的网页认证入口，请更新运行环境后重试。": "Harness 未提供有效的網頁認證入口，請更新執行環境後重試。",
  "无法停止 Harness 进程，请重试。": "無法停止 Harness 程序，請重試。",
  "Harness 未在限定时间内停止，请重试。": "Harness 未在限定時間內停止，請重試。",
  "Harness 停止操作被中断，请重试。": "Harness 停止操作被中斷，請重試。",
  "Shizuku 设备服务未在限定时间内退出，请在 Shizuku 中重启服务后重试；仍无响应时请完全退出并重开本应用。": "Shizuku 裝置服務未在限定時間內退出，請在 Shizuku 中重啟服務後重試；仍無響應時請完全退出並重開本應用。",
  "Shizuku 设备服务停止操作被中断，请重试。": "Shizuku 裝置服務停止操作被中斷，請重試。",
  "无法停止 Shizuku 设备服务，请重试。": "無法停止 Shizuku 裝置服務，請重試。",
  "Shizuku 设备服务正在停止，请稍后重试。": "Shizuku 裝置服務正在停止，請稍後重試。",
  "连接 Shizuku 设备服务超时。若刚更新过 Shizuku，请在 Shizuku 中停止服务后重新启动（或重启手机），再回到本页重试。": "連線 Shizuku 裝置服務超時。若剛更新過 Shizuku，請在 Shizuku 中停止服務後重新啟動（或重啟手機），再回到本頁重試。",
  "无法连接 Shizuku 设备服务。若刚更新过 Shizuku，请在 Shizuku 中停止服务后重新启动（或重启手机），再回到本页重试。": "無法連線 Shizuku 裝置服務。若剛更新過 Shizuku，請在 Shizuku 中停止服務後重新啟動（或重啟手機），再回到本頁重試。",
  "连接 Shizuku 设备服务被中断，请重试。": "連線 Shizuku 裝置服務被中斷，請重試。",
  "未能连接 Shizuku：请先打开 Shizuku 确认服务已启动；若刚更新过 Shizuku，请停止服务后重新启动。": "未能連線 Shizuku：請先開啟 Shizuku 確認服務已啟動；若剛更新過 Shizuku，請停止服務後重新啟動。",
  "Shizuku 连接已断开：请打开 Shizuku 重新启动服务后再连接。": "Shizuku 連線已斷開：請開啟 Shizuku 重新啟動服務後再連線。",
  "无法读取最新设置，请重试": "無法讀取最新設定，請重試",
  "暂时无法确认悬浮窗权限": "暫時無法確認懸浮窗權限",
  "无法读取悬浮球状态，正在重试": "無法讀取懸浮球狀態，正在重試",
  "设置已保存，但部分状态暂时无法确认，请稍后重试": "設定已儲存，但部分狀態暫時無法確認，請稍後重試",
  "运行时自检": "執行環境自檢",
  "自检会单独测试 Landlock 能力，不随会话权限切换。无沙箱会话可继续运行时，沙箱检查仍可能失败。": "自檢會單獨測試 Landlock 能力，不隨會話權限切換。無沙箱會話可繼續執行環境，沙箱檢查仍可能失敗。",
  "权限修复只补执行位和附件目录；修复后自动复检，不能安装内核沙箱能力。": "權限修復只補執行位和附件目錄；修復後自動複檢，不能安裝核心沙箱能力。",
  "本机 Landlock 沙箱不可用": "本機 Landlock 沙箱不可用",
  "修复执行权限后仍出现此结果，表示 Landlock 在当前内核或启动环境中不可用。若没有其他可用后端，要求沙箱的会话无法执行命令；反复修复权限或重装运行时不能补齐内核能力。": "修復執行權限後仍出現此結果，表示 Landlock 在當前核心或啟動環境中不可用。若沒有其他可用後端，要求沙箱的會話無法執行命令；反覆修復權限或重灌執行環境不能補齊核心能力。",
  "在当前 Harness 会话的权限预设中选择 danger-full-access，或输入 /permission danger-full-access，然后重试命令。": "在當前 Harness 會話的權限預設中選擇 danger-full-access，或輸入 /permission danger-full-access，然後重試命令。",
  "danger-full-access 会关闭 dsh 文件系统沙箱和命令审批。Android 应用沙箱仍在；PRoot 不提供额外的内核隔离。": "danger-full-access 會關閉 dsh 檔案系統沙箱和命令審批。Android 應用沙箱仍在；PRoot 不提供額外的核心隔離。",
  "重新安装或更新运行环境；修复权限不能恢复缺失的程序": "重新安裝或更新執行環境；修復權限不能恢復缺失的程式",
  "修复权限不能补齐内核能力；需要继续使用时，在当前 Harness 会话选择 danger-full-access": "修復權限不能補齊核心能力；需要繼續使用時，在當前 Harness 會話選擇 danger-full-access",
  "若「内核 Landlock 支持」同时报失败，说明内核不具备该能力，不要再查访客目录；否则再检查访客数据目录与运行日志": "若「核心 Landlock 支援」同時報失敗，表示核心不具備該能力，不必再檢查訪客資料目錄；否則再檢查訪客資料目錄與執行日誌",
  "对照「PTY 模块 node-pty」与「沙箱内 PTY」：裸 PTY 正常而沙箱内失败时，优先检查沙箱；两者都失败时，先检查 PTY 和运行日志": "對照「PTY 模組 node-pty」與「沙箱內 PTY」：裸 PTY 正常而沙箱內失敗時，優先檢查沙箱；兩者都失敗時，先檢查 PTY 和執行日誌",
  "在当前 Harness 会话的权限预设中选择 danger-full-access，或输入 /permission danger-full-access 后重试。此模式关闭 dsh 文件系统沙箱和命令审批；仅重启不会改变已有会话的权限。": "在當前 Harness 會話的權限預設中選擇 danger-full-access，或輸入 /permission danger-full-access 後重試。此模式關閉 dsh 檔案系統沙箱和命令審批；僅重啟不會改變已有會話的權限。",
  "不需要 bash 也能判断运行时哪一环断了：逐项检查 Shell、Node、沙箱启动器、内核 Landlock、PTY、访客数据目录、附件目录、硬链接、ripgrep 与 C 编译环境（cc/gcc/clang、make、python3），并给出结论与下一步。": "不需要 bash 也能判斷執行環境哪一環斷了：逐項檢查 Shell、Node、沙箱啟動器、核心 Landlock、PTY、訪客資料目錄、附件目錄、硬連結、ripgrep 與 C 編譯環境（cc/gcc/clang、make、python3），並給出結論與下一步。",
