  "当前使用的运行时、保留下来的上一版本，以及随安装包内置的版本。装新版本仍在运行环境页：内置更新，或填写 manifest 地址与 SHA-256。": "當前使用的執行環境、保留下來的上一版本，以及隨安裝包內建的版本。裝新版本仍在執行環境頁：內建更新，或填寫 manifest 地址與 SHA-256。",
  "上一版本是上一次安装时保留下来的完整副本，切换与删除都只动它。删除后无法恢复，也不再占用磁盘。": "上一版本是上一次安裝時保留下來的完整副本，切換與刪除都只動它。刪除後無法恢復，也不再佔用磁碟。",
  "运行中不能切换版本：请先停止运行环境与 Ubuntu 终端。": "執行中不能切換版本：請先停止執行環境與 Ubuntu 終端。",
  "删除上一版本会永久删掉这份副本，无法撤销；当前使用的版本不受影响。": "刪除上一版本會永久刪掉這份副本，無法撤銷；當前使用的版本不受影響。",
