  "版本库已满（{0} 个）：下载新版本会给未锁定的最旧版本腾位置；锁定的版本不会被自动淘汰。": "版本庫已滿（{0} 個）：下載新版本會給未鎖定的最舊版本騰位置；鎖定的版本不會被自動淘汰。",
  "版本库已满（{0} 个），且全部已锁定：下载新版本会被明确拒绝，需要先删除或解锁一个版本。": "版本庫已滿（{0} 個），且全部已鎖定：下載新版本會被明確拒絕，需要先刪除或解鎖一個版本。",
  "保留上一版本，可一键切回；装新版本仍在运行环境页": "保留上一版本，可一鍵切回；裝新版本仍在執行環境頁",
