  "从本项目的 GitHub 发布页读取带运行时清单的版本。安装要下载并校验整份 rootfs，所以不会自动查询。": "從本專案的 GitHub 釋出頁讀取帶執行環境清單的版本。安裝要下載並驗證整份 rootfs，所以不會自動查詢。",
