  "发布页上还没有带运行时清单的版本。": "釋出頁上還沒有帶執行環境清單的版本。",
  "清单里没有 dsh 版本：安装后以运行环境页显示的为准。": "清單裡沒有 dsh 版本：安裝後以執行環境頁顯示的為準。",
  "这个版本的清单没通过校验，只能查看、不能安装。": "這個版本的清單沒通過驗證，只能檢視、不能安裝。",
  "安装这个版本": "安裝這個版本",
  "安装会先自动备份会话，再下载、校验并切换新运行时；这一步失败不影响当前正在使用的版本。": "安裝會先自動備份會話，再下載、驗證並切換新執行環境；這一步失敗不影響當前正在使用的版本。",
  "会话备份": "會話備份",
  "会话备份保存在应用私有目录中，不会进入系统云备份或运行环境安装包。安装或更新运行环境前，应用会自动创建备份。": "會話備份儲存在應用私有目錄中，不會進入系統雲備份或執行環境安裝包。安裝或更新執行環境前，應用會自動建立備份。",
  "正在读取会话备份…": "正在讀取會話備份…",
  "暂时读不到会话备份列表": "暫時讀不到會話備份列表",
  "暂无会话备份。你可以手动创建，也可以等应用在安装运行环境前自动备份。": "暫無會話備份。你可以手動建立，也可以等應用在安裝執行環境前自動備份。",
  "{0} 个文件": "{0} 個檔案",
  "运行时版本未读到": "執行環境版本未讀到",
  "恢复": "恢復",
  "最多保留 {0} 份备份，总大小不超过 {1}；超出限制时会删除最旧的备份。恢复时只添加缺失的文件，不覆盖同名文件。": "最多保留 {0} 份備份，總大小不超過 {1}；超出限制時會刪除最舊的備份。恢復時只新增缺失的檔案，不覆蓋同名檔案。",
  "现在备份一次": "現在備份一次",
  "会话备份已创建": "會話備份已建立",
  "会话恢复完成：恢复 {0} 个文件，跳过 {1} 个已存在的文件。": "會話恢復完成：恢復 {0} 個檔案，跳過 {1} 個已存在的檔案。",
  "会话恢复完成：恢复 {0} 个文件。": "會話恢復完成：恢復 {0} 個檔案。",
  "会话备份已删除": "會話備份已刪除",
  "安装前已自动备份会话（{0}）": "安裝前已自動備份會話（{0}）",
  "安装前已自动备份会话（{0}）；为满足保留限制，已删除 {1} 份最旧的备份。": "安裝前已自動備份會話（{0}）；為滿足保留限制，已刪除 {1} 份最舊的備份。",
  "没有需要备份的会话数据，这次没有生成备份。": "沒有需要備份的會話資料，這次沒有生成備份。",
  "会话自动备份失败：{0}": "會話自動備份失敗：{0}",
  "原因未提供": "原因未提供",
  "即将安装运行时 {0}。继续后会替换 Ubuntu 运行时的系统目录；你的整个用户空间 /root（会话、模型密钥、Harness 设置、附件、技能、插件、工作区文件，以及你自己在 /root 下建的目录）都会保留，应用设置也不受影响；旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "即將安裝執行環境 {0}。繼續後會替換 Ubuntu 執行環境的系統目錄；你的整個使用者空間 /root（會話、模型金鑰、Harness 設定、附件、技能、外掛、工作區檔案，以及你自己在 /root 下建的目錄）都會保留，應用設定也不受影響；舊令牌與舊指令碼不會搬回，撞名沒搬回的項會留在「資料保留」裡可取回。",
  "即将安装运行时 {0}。继续后会替换 Ubuntu 运行时的系统目录；你的整个用户空间 /root 会保留（包括终端里用 dsh plugin add 装的插件），应用设置也不受影响，不需要重装任何东西；旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "即將安裝執行環境 {0}。繼續後會替換 Ubuntu 執行環境的系統目錄；你的整個使用者空間 /root 會保留（包括終端裡用 dsh plugin add 裝的外掛），應用設定也不受影響，不需要重灌任何東西；舊令牌與舊指令碼不會搬回，撞名沒搬回的項會留在「資料保留」裡可取回。",
  "开始前会先把当前会话自动备份一份（在「版本管理 → 会话备份」里能看到）。新镜像里的 dsh 版本可能与现在不同，读不出旧会话时可以用那份备份恢复。": "開始前會先把當前會話自動備份一份（在「版本管理 → 會話備份」裡能看到）。新映象裡的 dsh 版本可能與現在不同，讀不出舊會話時可以用那份備份恢復。",
