  "每天首次打开应用时提示一次；关闭后仍可手动检查更新。": "每天首次開啟應用時提示一次；關閉後仍可手動檢查更新。",
  "提醒偏好或日期未能持久保存，重启后可能再次提醒。": "提醒偏好或日期未能持久儲存，重啟後可能再次提醒。",
