  "本机没有可用的沙箱后端": "本機沒有可用的沙箱後端",
  "在要求沙箱的模式（例如 workspace-write）下，dsh 找不到可用的沙箱后端就会拒绝执行命令，这是它的 fail-closed 行为：bash 工具报「PTY shell exited during startup」通常是这条链的结果，不是工具本身坏了。": "在要求沙箱的模式（例如 workspace-write）下，dsh 找不到可用的沙箱後端就會拒絕執行命令，這是它的 fail-closed 行為：bash 工具報「PTY shell exited during startup」通常是這條鏈的結果，不是工具本身壞了。",
  "在 Harness 的权限预设里选择不启用沙箱的模式，然后重启运行环境。这是明确的能力降级：访客内不再有 Landlock 的文件系统隔离；PRoot 与 Android 应用沙箱仍然有效，但 PRoot 只是用户态模拟，不提供宿主内核没有的隔离能力。": "在 Harness 的權限預設裡選擇不啟用沙箱的模式，然後重啟執行環境。這是明確的能力降級：訪客內不再有 Landlock 的檔案系統隔離；PRoot 與 Android 應用沙箱仍然有效，但 PRoot 只是使用者態模擬，不提供宿主核心沒有的隔離能力。",
