  "这里点选过的目录会挂进访客：手机上的目录 → 访客内 /mnt/user/<序号>。访客里不再有 /sdcard，能看到哪些用户目录完全由这份列表决定。": "這裡點選過的目錄會掛進訪客：手機上的目錄 → 訪客內 /mnt/user/<序號>。訪客裡不再有 /sdcard，能看到哪些使用者目錄完全由這份列表決定。",
