  "T0 · 本机没有这一档": "T0 · 本機沒有這一檔",
  "当前系统没有「所有文件访问」这一档（Android 11 以下），目录白名单无法启用：这些设备上访客内不提供共享存储。这是用「用户点选的目录」取代 /sdcard 整体绑定的必然代价，不是故障；控制台上传与投递区照常可用。": "當前系統沒有「所有檔案存取」這一檔（Android 11 以下），目錄白名單無法啟用：這些裝置上訪客內不提供共享儲存。這是用「使用者點選的目錄」取代 /sdcard 整體繫結的必然代價，不是故障；主控台上傳與投遞區照常可用。",
  "还没有「所有文件访问」权限：现在不能选新目录，已经选好的目录也不会挂进访客。请点下面的按钮去系统设置开启；回到本页会自动重新检查。": "還沒有「所有檔案存取」權限：現在不能選新目錄，已經選好的目錄也不會掛進訪客。請點下面的按鈕去系統設定開啟；回到本頁會自動重新檢查。",
  "这一条当前不可用，但原生侧没有返回原因码；请移除后重新添加。": "這一條當前不可用，但原生側沒有返回原因碼；請移除後重新新增。",
  "目录当前不可用": "目錄當前不可用",
  "添加目录": "新增目錄",
  "去系统设置开启所有文件访问": "去系統設定開啟所有檔案存取",
  "移除": "移除",
  "每行下面两个路径：第一个是访客内的挂载点（/mnt/user/<序号>），第二个是这个目录在手机上的真实位置。": "每行下面兩個路徑：第一個是訪客內的掛載點（/mnt/user/<序號>），第二個是這個目錄在手機上的真實位置。",
  "不可用的条目仍然占着它的序号：访客里的挂载点会跳号（例如有 1、3 而没有 2）。这是刻意的稳定语义——移除别的条目不会让一个目录换到另一个挂载点上。": "不可用的條目仍然佔著它的序號：訪客裡的掛載點會跳號（例如有 1、3 而沒有 2）。這是刻意的穩定語義——移除別的條目不會讓一個目錄換到另一個掛載點上。",
  "目录白名单是 T2「所有文件访问」这一档的能力；未授予时只能查看，不能添加。": "目錄白名單是 T2「所有檔案存取」這一檔的能力；未授予時只能檢視，不能新增。",
  "目录改动在下次启动运行环境时生效：正在运行的访客不会热更新挂载点。": "目錄改動在下次啟動執行環境時生效：正在執行的訪客不會熱更新掛載點。",
  "已达上限：最多只能添加 {0} 个目录，请先移除一个再添加。": "已達上限：最多隻能新增 {0} 個目錄，請先移除一個再新增。",
  "本机系统没有「所有文件访问」这一档（需要 Android 11 及以上），目录白名单无法启用；这些设备上访客内不提供共享存储。": "本機系統沒有「所有檔案存取」這一檔（需要 Android 11 及以上），目錄白名單無法啟用；這些裝置上訪客內不提供共享儲存。",
  "还没有「所有文件访问」权限：现在不能选新目录，已选的目录也不会挂进访客。请先在系统设置里为本应用开启该权限，再回到本页重试。": "還沒有「所有檔案存取」權限：現在不能選新目錄，已選的目錄也不會掛進訪客。請先在系統設定裡為本應用開啟該權限，再回到本頁重試。",
  "这台设备上没有可用的目录选择器（部分精简系统移除了文件管理器），无法选择目录。": "這臺裝置上沒有可用的目錄選擇器（部分精簡系統移除了檔案管理器），無法選擇目錄。",
  "系统返回的选择结果不是可识别的目录，请重新选择一次目录。": "系統返回的選擇結果不是可識別的目錄，請重新選擇一次目錄。",
  "只能选择「内部共享存储」里的目录：SD 卡、U 盘以及下载页面里的位置都不支持。请从「内部共享存储」进入后再选目录。": "只能選擇「內部共享儲存」裡的目錄：SD 卡、U 盤以及下載頁面裡的位置都不支援。請從「內部共享儲存」進入後再選目錄。",
  "不能选择共享存储的根目录，请进入它下面的某个具体目录后再确认。": "不能選擇共享儲存的根目錄，請進入它下面的某個具體目錄後再確認。",
  "这个目录不在本机的内部共享存储范围内（例如来自副用户或工作资料），当前不支持。": "這個目錄不在本機的內部共享儲存範圍內（例如來自副使用者或工作資料），當前不支援。",
  "不能选择 Android/ 目录及其子目录，那里是应用私有数据。": "不能選擇 Android/ 目錄及其子目錄，那裡是應用私有資料。",
  "不能选择应用私有目录，请换一个共享存储里的普通目录。": "不能選擇應用私有目錄，請換一個共享儲存裡的普通目錄。",
  "这个位置已经不是真实目录（可能被删除、改名，或被替换成链接），请重新选择。": "這個位置已經不是真實目錄（可能被刪除、改名，或被替換成連結），請重新選擇。",
  "无法把这个选择解析成手机上的真实路径，请换一个目录再试。": "無法把這個選擇解析成手機上的真實路徑，請換一個目錄再試。",
  "这个目录当前不可读（可能已被删除、改名，或系统没有真正授权），请检查后重新选择。": "這個目錄當前不可讀（可能已被刪除、改名，或系統沒有真正授權），請檢查後重新選擇。",
  "这个目录名里有运行时不支持的字符（中文、空格或其它特殊符号），无法绑定进访客；请改用只含字母、数字、点、下划线和短横线的目录名。": "這個目錄名裡有執行環境不支援的字元（中文、空格或其它特殊符號），無法繫結進訪客；請改用只含字母、數字、點、下劃線和短橫線的目錄名。",
  "这个目录已经在列表里了，不用重复添加。": "這個目錄已經在列表裡了，不用重複新增。",
  "最多只能添加 {0} 个目录，请先移除一个再添加。": "最多隻能新增 {0} 個目錄，請先移除一個再新增。",
  "白名单保存失败（应用私有存储不可写），请稍后重试。": "白名單儲存失敗（應用私有儲存不可寫），請稍後重試。",
  "没有拿到要移除的目录路径，无法移除；请重新进入本页后再试。": "沒有拿到要移除的目錄路徑，無法移除；請重新進入本頁後再試。",
  "这条目录已经不在白名单里了（可能在别处被移除）；请点上面的「重新检查」刷新列表。": "這條目錄已經不在白名單裡了（可能在別處被移除）；請點上面的「重新檢查」重新整理列表。",
  "目录路径格式不符合要求，这一条没有被接受。": "目錄路徑格式不符合要求，這一條沒有被接受。",
  "白名单的本地记录已损坏，无法读取；请移除后重新添加目录。": "白名單的本地記錄已損壞，無法讀取；請移除後重新新增目錄。",
  "目录操作失败（错误码 {0}）。请重试；若持续失败，可先移除该条目再重新添加。": "目錄操作失敗（錯誤碼 {0}）。請重試；若持續失敗，可先移除該條目再重新新增。",
