  "已选择 {0} 个应用；勾选后点击保存白名单。": "已選擇 {0} 個應用；勾選後點選儲存白名單。",
  "无法读取应用列表，请在安卓设备上重试。": "無法讀取應用列表，請在安卓裝置上重試。",
  "列表里只有本应用。部分国产系统需要「读取应用列表」权限才能读取其他应用。": "列表裡只有本應用。部分國產系統需要「讀取應用列表」權限才能讀取其他應用。",
  "若系统没有弹出授权框，请到应用设置里手动开启。": "若系統沒有彈出授權框，請到應用設定裡手動開啟。",
