  "当前显示 {0} / {1}": "當前顯示 {0} / {1}",
  "C 编译器（cc / gcc / clang）": "C 編譯器（cc / gcc / clang）",
  "make 构建工具": "make 構建工具",
  "Python 3（node-gyp 的前提）": "Python 3（node-gyp 的前提）",
  "运行时里没有 C 编译器（cc、gcc、clang 都没有找到）": "執行環境裡沒有 C 編譯器（cc、gcc、clang 都沒有找到）",
  "找到了 C 编译器，但一次最小的编译加链接没有通过（通常是缺工具链的其余部分：binutils、C 库头文件，或没有可用的临时目录）": "找到了 C 編譯器，但一次最小的編譯加連結沒有通過（通常是缺工具鏈的其餘部分：binutils、C 庫標頭檔案，或沒有可用的臨時目錄）",
  "编译器文件在，但探测没有拿到它的退出码（进程没起来、超时被杀，或连可写的产物目录都没有），因此无法确认它能编译": "編譯器檔案在，但探測沒有拿到它的退出碼（程序沒起來、超時被殺，或連可寫的產物目錄都沒有），因此無法確認它能編譯",
  "运行时里没有 make": "執行環境裡沒有 make",
  "找到了 make，但它没能正常回答版本查询": "找到了 make，但它沒能正常回答版本查詢",
  "make 文件在，但探测没有拿到它的退出码（进程没起来或超时），因此无法确认它能用": "make 檔案在，但探測沒有拿到它的退出碼（程序沒起來或超時），因此無法確認它能用",
  "运行时里没有 python3": "執行環境裡沒有 python3",
  "找到了 python3，但它没能正常回答版本查询": "找到了 python3，但它沒能正常回答版本查詢",
  "python3 文件在，但探测没有拿到它的退出码（进程没起来或超时），因此无法确认它能用": "python3 檔案在，但探測沒有拿到它的退出碼（程序沒起來或超時），因此無法確認它能用",
  "本应用不内置编译器，也不代为安装：需要现场编译原生模块（node-gyp 一类）的插件在当前设备上装不上。要自己补，可在运行时自带的 Ubuntu 终端里尝试安装 Debian/Ubuntu 系的 build-essential —— 运行时基于 ubuntu-base-24.04、apt 存在，但访客内能否联网取包尚未验证。": "本應用不內建編譯器，也不代為安裝：需要現場編譯原生模組（node-gyp 一類）的外掛在當前裝置上裝不上。要自己補，可在執行環境自帶的 Ubuntu 終端裡嘗試安裝 Debian/Ubuntu 系的 build-essential —— 執行環境基於 ubuntu-base-24.04、apt 存在，但訪客內能否聯網取包尚未驗證。",
  "在运行时自带的 Ubuntu 终端里补齐该工具链（Debian/Ubuntu 系是 build-essential），或先在该终端手动编译一个最小程序看具体报错；补齐之前需要现场编译原生模块的插件装不上。": "在執行環境自帶的 Ubuntu 終端裡補齊該工具鏈（Debian/Ubuntu 系是 build-essential），或先在該終端手動編譯一個最小程式看具體報錯；補齊之前需要現場編譯原生模組的外掛裝不上。",
  "按不可用处理：需要现场编译原生模块的插件在当前设备上装不上。可在运行时自带的 Ubuntu 终端里手动跑一次 cc --version 与一次最小编译，看是不是探测本身被挡住了。": "按不可用處理：需要現場編譯原生模組的外掛在當前裝置上裝不上。可在執行環境自帶的 Ubuntu 終端裡手動跑一次 cc --version 與一次最小編譯，看是不是探測本身被擋住了。",
  "本应用不内置编译器，也不代为安装：make 是 node-gyp 构建原生模块的必需项，缺它时含原生模块的插件在当前设备上装不上。要自己补，可在运行时自带的 Ubuntu 终端里尝试安装 build-essential 或单装 make（apt 存在，但访客内能否联网取包尚未验证）。": "本應用不內建編譯器，也不代為安裝：make 是 node-gyp 構建原生模組的必需項，缺它時含原生模組的外掛在當前裝置上裝不上。要自己補，可在執行環境自帶的 Ubuntu 終端裡嘗試安裝 build-essential 或單裝 make（apt 存在，但訪客內能否聯網取包尚未驗證）。",
  "node-gyp 需要一个能正常运行的 GNU make；可在运行时自带的 Ubuntu 终端里手动跑一次 make --version 看具体报错。": "node-gyp 需要一個能正常執行的 GNU make；可在執行環境自帶的 Ubuntu 終端裡手動跑一次 make --version 看具體報錯。",
  "按不可用处理；可在运行时自带的 Ubuntu 终端里手动跑一次 make --version 确认。": "按不可用處理；可在執行環境自帶的 Ubuntu 終端裡手動跑一次 make --version 確認。",
  "本应用不内置编译器，也不代为安装：node-gyp 依赖 python3，缺它时含原生模块的插件在当前设备上装不上；带 Python 3 的运行时包不会缺这一项，请先重装或更新运行时。": "本應用不內建編譯器，也不代為安裝：node-gyp 依賴 python3，缺它時含原生模組的外掛在當前裝置上裝不上；帶 Python 3 的執行環境包不會缺這一項，請先重灌或更新執行環境。",
  "node-gyp 需要一个能正常启动的 python3；可在运行时自带的 Ubuntu 终端里手动跑一次 python3 --version 看具体报错。": "node-gyp 需要一個能正常啟動的 python3；可在執行環境自帶的 Ubuntu 終端裡手動跑一次 python3 --version 看具體報錯。",
  "按不可用处理；可在运行时自带的 Ubuntu 终端里手动跑一次 python3 --version 确认。": "按不可用處理；可在執行環境自帶的 Ubuntu 終端裡手動跑一次 python3 --version 確認。",
  "通过 npm 包名或链接导入": "通過 npm 包名或連結匯入",
  "支持 npm 包名、HTTPS 压缩包直链和 git+https 仓库地址。导入时不执行包内的安装脚本；来源校验不通过时不会下载。": "支援 npm 包名、HTTPS 壓縮包直鏈和 git+https 倉庫地址。匯入時不執行包內的安裝指令碼；來源驗證不通過時不會下載。",
