  "通过链接导入时，可填写预期包名，以核对安装结果；如果链接中有多个插件包，可用它指定要安装的包。": "通過連結匯入時，可填寫預期包名，以核對安裝結果；如果連結中有多個外掛包，可用它指定要安裝的包。",
