  "暂时无法确认运行环境是否支持 git，请稍后重试或改用 https 直链": "暫時無法確認執行環境是否支援 git，請稍後重試或改用 https 直鏈",
  "插件数据超过 16 MiB，请清理插件数据后重试（原版本保持不变）": "外掛資料超過 16 MiB，請清理外掛資料後重試（原版本保持不變）",
  "插件数据目录里有不安全的链接，已放弃更新（原版本保持不变）": "外掛資料目錄裡有不安全的連結，已放棄更新（原版本保持不變）",
  "这个插件没有可回滚的上一版": "這個外掛沒有可回滾的上一版",
