  "运行环境未预装 C 编译器。安装后可在「设置 → 版本管理 → 运行时自检」查看可用工具；缺少可选工具不影响基本使用。如需编译代码，请自行安装所需工具链。": "執行環境未預裝 C 編譯器。安裝後可在「設定 → 版本管理 → 執行環境自檢」檢視可用工具；缺少可選工具不影響基本使用。如需編譯程式碼，請自行安裝所需工具鏈。",
