  "命令直接跑在设备上，不在 Ubuntu 里；Shizuku 没授权时也能打开，只是设备工具不可用，Ubuntu 终端与 Harness 不受影响。": "命令直接跑在裝置上，不在 Ubuntu 裡；Shizuku 沒授權時也能開啟，只是裝置工具不可用，Ubuntu 終端與 Harness 不受影響。",
