  "总开关、任务与运行记录、规则与每应用参数": "總開關、任務與執行記錄、規則與每應用引數",
  "无障碍、副屏与自动参数": "無障礙、副屏與自動引數",
  "自动化可能误点或误读界面，请只对自己有权操作的应用启用。": "自動化可能誤點或誤讀介面，請只對自己有權操作的應用啟用。",
  "无障碍自动化是你自行开启、自行选择目标应用的能力；请只对自己有权操作的应用启用。": "無障礙自動化是你自行開啟、自行選擇目標應用的能力；請只對自己有權操作的應用啟用。",
  "自动化可能误点或误读界面，涉及支付、验证码与隐私信息的页面请自行确认，由此产生的后果由使用者承担。": "自動化可能誤點或誤讀介面，涉及支付、驗證碼與隱私資訊的頁面請自行確認，由此產生的後果由使用者承擔。",
  "该能力只在本机生效：服务不做后台监听，也不批量上传界面；只有你让 AI 执行操作时，读取到的界面节点才会按需进入当前会话与所选模型服务。": "該能力只在本機生效：服務不做後臺監聽，也不批次上傳介面；只有你讓 AI 執行操作時，讀取到的介面節點才會按需進入當前會話與所選模型服務。",
  "查看完整免责说明": "檢視完整免責說明",
  "关于自动化（无障碍）功能": "關於自動化（無障礙）功能",
  "本功能会按你（或你授权的 AI 助手）写入的规则，在你指定的应用处于前台时自动点击、滑动、按键或等待。规则由你确认后长期生效，因此：": "本功能會按你（或你授權的 AI 助手）寫入的規則，在你指定的應用處於前臺時自動點選、滑動、按鍵或等待。規則由你確認後長期生效，因此：",
  "自动化操作可能误点：界面、文案与控件标识会随应用更新而变化，规则可能在你没有预期的地方生效，也可能在你预期的地方失效。": "自動化操作可能誤點：介面、文案與控制元件標識會隨應用更新而變化，規則可能在你沒有預期的地方生效，也可能在你預期的地方失效。",
  "涉及支付、验证码、密码、生物识别与权限申请的页面一律会被跳过，且这一限制没有开关；但「被跳过」不等于「界面绝对安全」，请不要依赖本功能替你判断风险。": "涉及支付、驗證碼、密碼、生物識別與權限申請的頁面一律會被跳過，且這一限制沒有開關；但「被跳過」不等於「介面絕對安全」，請不要依賴本功能替你判斷風險。",
  "请自行确认每条规则的作用范围与次数上限；因规则配置错误、来源不明或与界面不匹配所导致的后果，由使用者自行承担。": "請自行確認每條規則的作用範圍與次數上限；因規則配置錯誤、來源不明或與介面不匹配所導致的後果，由使用者自行承擔。",
  "本功能默认关闭，需要你在应用内显式开启，并在系统设置里手动授予无障碍权限；关闭后立即停止自动操作。": "本功能預設關閉，需要你在應用內顯式開啟，並在系統設定裡手動授予無障礙權限；關閉後立即停止自動操作。",
  "本功能不收集、不上传你的界面内容、输入内容与规则内容；本机只记录「发生了一次动作、结果是成功还是失败」这类不含内容的审计条目。": "本功能不收集、不上傳你的介面內容、輸入內容與規則內容；本機只記錄「發生了一次動作、結果是成功還是失敗」這類不含內容的審計條目。",
  "请勿将本功能用于违反应用服务条款、绕过付费或验证、刷量、抢购等用途。": "請勿將本功能用於違反應用服務條款、繞過付費或驗證、刷量、搶購等用途。",
  "我已阅读并理解上述说明，并自行承担规则配置与使用带来的后果": "我已閱讀並理解上述說明，並自行承擔規則配置與使用帶來的後果",
