  "恢复默认": "恢復預設",
  "无法清除背景，请重试": "無法清除背景，請重試",
  "不需要 bash 也能判断运行时哪一环断了：逐项检查 Shell、Node、沙箱启动器、内核 Landlock、PTY、访客数据目录、附件目录、硬链接、ripgrep 与 C 编译环境（cc/gcc/clang、make、python3），再由宿主补上插件链接、无障碍服务、副屏所需的悬浮窗权限与系统 WebView 四项设备事实，并给出结论与下一步。": "不需要 bash 也能判斷執行環境哪一環斷了：逐項檢查 Shell、Node、沙箱啟動器、核心 Landlock、PTY、訪客資料目錄、附件目錄、硬連結、ripgrep 與 C 編譯環境（cc/gcc/clang、make、python3），再由宿主補上外掛連結、無障礙服務、副屏所需的懸浮窗權限與系統 WebView 四項裝置事實，並給出結論與下一步。",
  "系统 WebView 版本": "系統 WebView 版本",
  "WebView 版本格式无效": "WebView 版本格式無效",
  "插件链接（已启用的插件）": "外掛連結（已啟用的外掛）",
  "无障碍服务": "無障礙服務",
  "副屏所需的悬浮窗权限": "副屏所需的懸浮窗權限",
  "系统 WebView": "系統 WebView",
  "有已启用的插件在运行时里缺少链接文件，该插件的工具这次加载不上": "有已啟用的外掛在執行環境裡缺少連結檔案，該外掛的工具這次載入不上",
  "到「插件设置」页点「立即修复插件」重新链接；仍失败就重新安装该插件。「修复运行时权限」不管这一项。": "到「外掛設定」頁點「立即修復外掛」重新連結；仍失敗就重新安裝該外掛。「修復執行環境權限」不管這一項。",
  "上一次插件修复没有成功——插件文件仍然不可用（多见于保留区已无副本，只能重装）": "上一次外掛修復沒有成功——外掛檔案仍然不可用（多見於保留區已無副本，只能重灌）",
  "到「插件设置」页点「立即修复插件」重试；反复失败请重新安装该插件，或导出运行日志反馈。": "到「外掛設定」頁點「立即修復外掛」重試；反覆失敗請重新安裝該外掛，或匯出執行日誌反饋。",
  "这次没读到插件状态（插件管理器还没就绪，或运行时尚未安装完成）": "這次沒讀到外掛狀態（外掛管理器還沒就緒，或執行環境尚未安裝完成）",
  "稍后重新运行自检即可确认；插件列表本身以「插件设置」页显示的为准。": "稍後重新執行自檢即可確認；外掛列表本身以「外掛設定」頁顯示的為準。",
  "无障碍服务未连接。它只被「应用自动化能力」用到，属于可选功能，不影响 bash 与插件": "無障礙服務未連線。它只被「應用自動化能力」用到，屬於可選功能，不影響 bash 與外掛",
  "需要该功能时，在系统设置 → 无障碍里打开本应用的无障碍服务；不需要就不用处理。": "需要該功能時，在系統設定 → 無障礙裡開啟本應用的無障礙服務；不需要就不用處理。",
  "这次没读到无障碍服务的连接状态": "這次沒讀到無障礙服務的連線狀態",
  "需要该功能时，到系统设置 → 无障碍里确认本应用的服务是开启状态；不影响其余功能。": "需要該功能時，到系統設定 → 無障礙裡確認本應用的服務是開啟狀態；不影響其餘功能。",
  "没有「显示在其他应用上层」权限，副屏用不了（属于可选功能）": "沒有「顯示在其他應用上層」權限，副屏用不了（屬於可選功能）",
  "需要副屏时，在系统设置 → 应用 → 本应用里授予悬浮窗权限；不需要就不用处理。": "需要副屏時，在系統設定 → 應用 → 本應用裡授予懸浮窗權限；不需要就不用處理。",
  "这次没读到悬浮窗权限的状态": "這次沒讀到懸浮窗權限的狀態",
  "需要副屏时，到系统设置里确认本应用已获得「显示在其他应用上层」权限；不影响其余功能。": "需要副屏時，到系統設定裡確認本應用已獲得「顯示在其他應用上層」權限；不影響其餘功能。",
  "系统 WebView 不可用——应用界面本身就是用它渲染的，此时界面通常已经打不开": "系統 WebView 不可用——應用介面本身就是用它渲染的，此時介面通常已經打不開",
  "在系统应用商店更新或重新启用 Android System WebView（或 Chrome）；它是系统组件，应用侧无法代装或替换。": "在系統應用商店更新或重新啟用 Android System WebView（或 Chrome）；它是系統元件，應用側無法代裝或替換。",
  "这次没读到系统 WebView 的信息（查询被系统拒绝或还没初始化），无法确认它的版本": "這次沒讀到系統 WebView 的資訊（查詢被系統拒絕或還沒初始化），無法確認它的版本",
  "界面能正常打开时通常只是查询失败，不用处理；界面显示异常时再更新系统 WebView 后重试。": "介面能正常開啟時通常只是查詢失敗，不用處理；介面顯示異常時再更新系統 WebView 後重試。",
  "数据清理": "資料清理",
