  "可用，但保护降了一档": "可用，但保護降了一檔",
  "根通道开关没有打开（打开后才会检测这台设备支不支持）": "根通道開關沒有開啟（開啟後才會檢測這臺裝置支不支援）",
  "关着的时候本应用不拉 su，所以现在还不知道这台设备支不支持 KernelSU；打开开关后才会检测。": "關著的時候本應用不拉 su，所以現在還不知道這臺裝置支不支援 KernelSU；開啟開關後才會檢測。",
  "这台设备没有可用的 KernelSU": "這臺裝置沒有可用的 KernelSU",
  "KernelSU 还没有给本应用授权": "KernelSU 還沒有給本應用授權",
  "设备上的 root 不是 KernelSU，本应用只走 KernelSU": "裝置上的 root 不是 KernelSU，本應用只走 KernelSU",
  "命令照常执行，但这台设备给不了完整的隔离：静态审查已按严格档收紧，对 /dev 的遮蔽没有生效": "命令照常執行，但這臺裝置給不了完整的隔離：靜態審查已按嚴格檔收緊，對 /dev 的遮蔽沒有生效",
  "到「根通道」设置里打开开关": "到「根通道」設定裡開啟開關",
  "到 KernelSU 管理器里给本应用授权": "到 KernelSU 管理器裡給本應用授權",
  "没有根通道时，Shizuku 的设备 Shell 仍可用（命令以 shell 身份执行，没有 UID 0）": "沒有根通道時，Shizuku 的裝置 Shell 仍可用（命令以 shell 身份執行，沒有 UID 0）",
  "一次看清 Shizuku、根通道、无障碍、副屏、截图与中文输入现在能不能用，以及不能用的原因。": "一次看清 Shizuku、根通道、無障礙、副屏、截圖與中文輸入現在能不能用，以及不能用的原因。",
  "打开后，AI 的设备命令可以以 UID 0 执行：命令先过静态审查，再在私有命名空间里跑，并尽量把核心分区挂成只读。默认关闭。": "開啟後，AI 的裝置命令可以以 UID 0 執行：命令先過靜態審查，再在私有名稱空間裡跑，並儘量把核心分割槽掛成只讀。預設關閉。",
  "正在读取根通道状态…": "正在讀取根通道狀態…",
  "启用根通道": "啟用根通道",
  "当前可用": "當前可用",
  "su 版本：{0}": "su 版本：{0}",
  "开关开着但还没法用：设备命令仍走 Shizuku（shell 身份，没有 UID 0）。": "開關開著但還沒法用：裝置命令仍走 Shizuku（shell 身份，沒有 UID 0）。",
  "隔离不完整，少了这些保护：": "隔離不完整，少了這些保護：",
  "命令仍会执行，但静态审查已按严格档收紧：挂载、写 /dev 下的设备节点、加载内核模块这类命令一律拒绝。": "命令仍會執行，但靜態審查已按嚴格檔收緊：掛載、寫 /dev 下的裝置節點、載入核心模組這類命令一律拒絕。",
  "UID 0 的命令能改动系统分区与内核参数。审查放行的命令会在私有命名空间里执行，但它仍然是 UID 0——不确定时请保持关闭。": "UID 0 的命令能改動系統分割槽與核心引數。審查放行的命令會在私有名稱空間裡執行，但它仍然是 UID 0——不確定時請保持關閉。",
  "保存根通道开关失败：{0}": "儲存根通道開關失敗：{0}",
  "打开后，AI 的设备命令可以以 UID 0 执行。严格档拦 mount、dd、insmod、setprop；最大档只拦刷机、块设备、核心分区写入、数据销毁与电源。默认关闭。": "開啟後，AI 的裝置命令可以以 UID 0 執行。嚴格檔攔 mount、dd、insmod、setprop；最大檔只攔刷機、塊裝置、核心分割槽寫入、資料銷燬與電源。預設關閉。",
  "根通道模式": "根通道模式",
