  "最大档：mount、dd（普通文件）、insmod、setprop（普通属性）放行；刷机、块设备、核心分区写入、数据销毁与电源仍拦截。": "最大檔：mount、dd（普通檔案）、insmod、setprop（普通屬性）放行；刷機、塊裝置、核心分割槽寫入、資料銷燬與電源仍攔截。",
  "严格档：mount、dd、insmod、setprop 一律拒绝；适合没有 KernelSU App Profile 兜底的设备。": "嚴格檔：mount、dd、insmod、setprop 一律拒絕；適合沒有 KernelSU App Profile 兜底的裝置。",
  "命令仍会执行，但静态审查已按当前档位收紧；最大档在降级设备上等于无沙箱 root，风险更高。": "命令仍會執行，但靜態審查已按當前檔位收緊；最大檔在降級裝置上等於無沙箱 root，風險更高。",
  "UID 0 的命令能改动系统数据。护栏是静态文本过滤，不是硬沙箱；不确定时请保持关闭。": "UID 0 的命令能改動系統資料。護欄是靜態文本過濾，不是硬沙箱；不確定時請保持關閉。",
