  "这台设备的 unshare 用不了，命令会跑在宿主命名空间里": "這臺裝置的 unshare 用不了，命令會跑在宿主名稱空間裡",
  "拿不到 PID 隔离，命令看不到、也影响不到别的进程组之外的东西会更多": "拿不到 PID 隔離，命令看不到、也影響不到別的程序組之外的東西會更多",
  "挂载传播关系切不开，隔离里做的挂载可能影响到外面": "掛載傳播關係切不開，隔離裡做的掛載可能影響到外面",
  "没能把 /dev/block 遮掉，命令理论上能看到块设备节点": "沒能把 /dev/block 遮掉，命令理論上能看到塊裝置節點",
  "这一档没有做 /dev 遮蔽": "這一檔沒有做 /dev 遮蔽",
  "有核心分区没能重新挂成只读": "有核心分割槽沒能重新掛成只讀",
  "/proc 没能按隔离重新挂载": "/proc 沒能按隔離重新掛載",
  "这台设备没有 setpriv，命令跑在完整的 root 能力集里": "這臺裝置沒有 setpriv，命令跑在完整的 root 能力集裡",
  "自动化任务": "自動化任務",
  "这里显示 AI 当前执行的任务；如果暂时无法读取，会明确提示。你也可以随时在此停止任务。": "這裡顯示 AI 當前執行的任務；如果暫時無法讀取，會明確提示。你也可以隨時在此停止任務。",
  "正在读取当前任务…": "正在讀取當前任務…",
