  "无障碍服务没有连上，读不到任务状态。": "無障礙服務沒有連上，讀不到任務狀態。",
  "这不是「没有任务」：连接恢复后再读一次才知道现在是什么状态。": "這不是「沒有任務」：連線恢復後再讀一次才知道現在是什麼狀態。",
