  "输入文字": "輸入文字",
  "滚动": "滾動",
  "进度：已收口 {0} 步，待执行 {1} 步，共 {2} 步。": "進度：已收口 {0} 步，待執行 {1} 步，共 {2} 步。",
  "最近一次：{0}": "最近一次：{0}",
  " · 已试 {0} 次": " · 已試 {0} 次",
  "停止只把剩下的步骤标成跳过，已经发出去的那一步不会撤回。": "停止只把剩下的步驟標成跳過，已經發出去的那一步不會撤回。",
  "停止这个任务": "停止這個任務",
  "已经停止，剩下的步骤都标成了跳过。": "已經停止，剩下的步驟都標成了跳過。",
  "停止失败（{0}）": "停止失敗（{0}）",
  "无障碍服务没有连上，现在叫不停它": "無障礙服務沒有連上，現在叫不停它",
  "现在没有任务可停止": "現在沒有任務可停止",
  "重新读取": "重新讀取",
  "目标帧率": "目標幀率",
  "画面年龄": "畫面年齡",
  "输入后首帧间隔估计": "輸入後首幀間隔估計",
  "尚未测到": "尚未測到",
  "{0} 毫秒": "{0} 毫秒",
  "{0} 毫秒（最近 {1} 次平均 {2} 毫秒）": "{0} 毫秒（最近 {1} 次平均 {2} 毫秒）",
  "…": "…",
  "清理": "清理",
  "缓存、插件数据与运行时残留都在这里回收；运行环境本身在「重置运行环境」里处理。": "快取、外掛資料與執行環境殘留都在這裡回收；執行環境本身在「重置執行環境」裡處理。",
  "已自动保存": "已自動儲存",
  "保存中...": "儲存中...",
  "悬浮球需要悬浮窗权限": "懸浮球需要懸浮窗權限",
  "后台保持的通知权限未开启": "後臺保持的通知權限未開啟",
  "前台服务被系统拦截": "前臺服務被系統攔截",
  "悬浮球启动失败": "懸浮球啟動失敗",
  "悬浮球要获得「显示在其他应用上层」权限，才能浮现在其他应用之上。请在系统设置中开启该权限，返回应用后重新打开悬浮球开关。": "懸浮球要獲得「顯示在其他應用上層」權限，才能浮現在其他應用之上。請在系統設定中開啟該權限，返回應用後重新開啟懸浮球開關。",
  "Android 13 及以上，前台服务的常驻通知需要通知权限。缺少它时服务仍能启动，只是不显示这条通知，系统任务管理器里仍能看到本应用在运行；是否生效要看「前台服务」状态行。建议允许通知，方便确认后台保持在跑。": "Android 13 及以上，前臺服務的常駐通知需要通知權限。缺少它時服務仍能啟動，只是不顯示這條通知，系統工作管理員裡仍能看到本應用在執行；是否生效要看「前臺服務」狀態行。建議允許通知，方便確認後臺保持在跑。",
  "系统没有允许「后台保持」的前台服务启动。常见原因是厂商 ROM 的自启动、后台运行或省电策略拦截；小米、OPPO、vivo、荣耀、华为、三星都有这类开关，只是叫法不同。请按下面几项逐项检查：": "系統沒有允許「後臺保持」的前臺服務啟動。常見原因是廠商 ROM 的自啟動、後臺執行或省電策略攔截；小米、OPPO、vivo、榮耀、華為、三星都有這類開關，只是叫法不同。請按下面幾項逐項檢查：",
  "系统没有允许悬浮球的前台服务启动。常见原因是厂商 ROM 的自启动、后台运行或省电策略拦截；小米、OPPO、vivo、荣耀、华为、三星都有这类开关，只是叫法不同。请按下面几项逐项检查：": "系統沒有允許懸浮球的前臺服務啟動。常見原因是廠商 ROM 的自啟動、後臺執行或省電策略攔截；小米、OPPO、vivo、榮耀、華為、三星都有這類開關，只是叫法不同。請按下面幾項逐項檢查：",
  "允许自启动：HyperOS 在「应用设置 → 授权管理 → 自启动管理」，ColorOS 在「应用 → 自启动」，OriginOS 在「i管家 → 权限管理 → 自启动」": "允許自啟動：HyperOS 在「應用設定 → 授權管理 → 自啟動管理」，ColorOS 在「應用 → 自啟動」，OriginOS 在「i管家 → 權限管理 → 自啟動」",
  "放开后台运行：HyperOS 在「应用信息 → 省电策略」选「无限制」，ColorOS 在「应用信息 → 耗电管理」打开「允许后台运行」，OriginOS 在「电池 → 后台耗电管理」允许「后台高耗电」": "放開後臺執行：HyperOS 在「應用資訊 → 省電策略」選「無限制」，ColorOS 在「應用資訊 → 耗電管理」開啟「允許後臺執行」，OriginOS 在「電池 → 後臺耗電管理」允許「後臺高耗電」",
  "在系统「电池」里把本应用排除在电池优化之外：ColorOS 叫「耗电异常优化」，多数 ROM 叫「电池优化」，选「不优化」或「无限制」": "在系統「電池」裡把本應用排除在電池最佳化之外：ColorOS 叫「耗電異常最佳化」，多數 ROM 叫「電池最佳化」，選「不最佳化」或「無限制」",
  "在最近任务列表里给本应用加锁：下拉卡片，或点卡片右上角菜单里的「锁定」，避免被一键清理": "在最近任務列表裡給本應用加鎖：下拉卡片，或點卡片右上角選單裡的「鎖定」，避免被一鍵清理",
  "荣耀和华为在「应用启动管理」里关掉自动管理，再勾上「允许自启动」和后台那一项：荣耀叫「允许后台活动」，华为叫「允许后台启动」；三星在「电池 → 后台使用限制 → 从不休眠的应用」里加入本应用，并在应用信息 →「电池」选「无限制」": "榮耀和華為在「應用啟動管理」裡關掉自動管理，再勾上「允許自啟動」和後臺那一項：榮耀叫「允許後臺活動」，華為叫「允許後臺啟動」；三星在「電池 → 後臺使用限制 → 從不休眠的應用」裡加入本應用，並在應用資訊 →「電池」選「無限制」",
  "菜单名会随系统版本变化，在设置顶部搜「自启动」或「耗电管理」通常比逐层找更快。": "選單名會隨系統版本變化，在設定頂部搜「自啟動」或「耗電管理」通常比逐層找更快。",
  "悬浮球界面在当前系统上创建失败。请尝试重启应用后再开启；如果反复出现，请在「诊断与日志」中导出记录后反馈。": "懸浮球介面在當前系統上建立失敗。請嘗試重啟應用後再開啟；如果反覆出現，請在「診斷與日誌」中匯出記錄後反饋。",
