  "免费声明": "免費宣告",
  "本软件完全免费且开源（MIT 许可），官方下载渠道只有本项目的 GitHub Releases。": "本軟體完全免費且開源（MIT 許可），官方下載渠道只有本專案的 GitHub Releases。",
  "没有付费版、付费激活或付费代装。如果你为它付过钱，请立即申请退款，并向收费平台举报。": "沒有付費版、付費啟用或付費代裝。如果你為它付過錢，請立即申請退款，並向收費平臺舉報。",
  "模型 API 的费用由模型供应商收取，需要你自己承担；软件本身不收取任何费用。": "模型 API 的費用由模型供應商收取，需要你自己承擔；軟體本身不收取任何費用。",
  "本项目与任何第三方售卖、代装或所谓「内部渠道」无关。": "本專案與任何第三方售賣、代裝或所謂「內部渠道」無關。",
  "点「我已了解」后开始配置；右上角仍可跳过引导。": "點「我已瞭解」後開始配置；右上角仍可跳過引導。",
