  "纵深防御说明：硬编码规则覆盖 Root、Shizuku、无障碍、文件通道、副屏与访客挂载。前 17 项开启后默认仍保留沙箱隔离与 Root 应用警告确认页；只有显式勾选第四组对应开关，才会进一步放开沙箱、确认页或宿主能力，关闭开关即刻恢复全部硬编码拦截。": "縱深防禦說明：硬編碼規則覆蓋 Root、Shizuku、無障礙、檔案通道、副螢幕與訪客掛載。前 17 項開啟後預設仍保留沙箱隔離與 Root 應用程式警告確認頁；只有明確勾選第四組對應開關，才會進一步放開沙箱、確認頁或宿主能力，關閉開關即刻恢復全部硬編碼攔截。",
